package com.bank.kyc;

import java.util.logging.Logger;

public class NameMatcher {

    private static final Logger log = Logger.getLogger(NameMatcher.class.getName());

    public int editDistance(String a, String b) {
        int m = a.length(), n = b.length();
        int[][] dp = new int[m + 1][n + 1];
        for (int i = 0; i <= m; i++) dp[i][0] = i;     // delete all of A's prefix
        for (int j = 0; j <= n; j++) dp[0][j] = j;     // insert all of B's prefix
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (a.charAt(i - 1) == b.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1];        // match ⇒ no edit
                } else {
                    dp[i][j] = 1 + Math.min(dp[i - 1][j - 1],       // replace
                                   Math.min(dp[i - 1][j],           // delete
                                            dp[i][j - 1]));          // insert
                }
            }
        }
        int result = dp[m][n];
        log.info(() -> "editDistance(" + a + "," + b + ") = " + result);
        return result;
    }
}
