package com.bank.kyc;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class EditDistanceDemo {

    private static final Logger log = Logger.getLogger(EditDistanceDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — KYC Name Matcher (Edit Distance)");
        NameMatcher matcher = new NameMatcher();
        log.info("Rajesh vs Rajes → " + matcher.editDistance("Rajesh", "Rajes"));   // 1
        log.info("horse vs ros → " + matcher.editDistance("horse", "ros"));          // 3
    }
}
